def transform(grid):
    g=[r[:] for r in grid]
    pts=[(r,c) for r,row in enumerate(g) for c,v in enumerate(row) if v==5]
    r0=min(r for r,c in pts); r1=max(r for r,c in pts)
    c0=min(c for r,c in pts); c1=max(c for r,c in pts)
    mr=(r0+r1)//2; mc=(c0+c1)//2
    for r,row in enumerate(g):
      for c,v in enumerate(row):
        if v not in (0,5):
          # identify marker's quadrant relative to frame, project to quadrant, duplicate diagonally
          qr=0 if r<r0 else 1 if r>r1 else (0 if r<=mr else 1)
          qc=0 if c<c0 else 1 if c>c1 else (0 if c<=mc else 1)
          for rr in range(r0+1,r1):
            for cc in range(c0+1,c1):
              ar=0 if rr<=mr else 1; ac=0 if cc<=mc else 1
              if (ar,ac) in ((qr,qc),(1-qr,1-qc)):
                g[rr][cc]=v
    return g
